using System.Text.Json;
namespace ThaiModelStudio;
public sealed record BlenderMenuAction(string Kind,string Id,string Label,string ThaiLabel,Dictionary<string,string> Properties,bool Resolved);
public sealed record BlenderMenu(string Id,string Name,string ThaiName,string Kind,List<BlenderMenuAction> Items);
public sealed class BlenderMenuService {
 public IReadOnlyList<BlenderMenu> Menus {get;}
 public BlenderMenuService(){var path=Path.Combine(AppContext.BaseDirectory,"engine","blender_menus.json"); if(!File.Exists(path)){Menus=[];return;} using var d=JsonDocument.Parse(File.ReadAllText(path)); var all=new List<BlenderMenu>(); foreach(var m in d.RootElement.GetProperty("menus").EnumerateArray()){var items=new List<BlenderMenuAction>(); if(m.TryGetProperty("items",out var ia))foreach(var i in ia.EnumerateArray()){var p=new Dictionary<string,string>(); if(i.TryGetProperty("properties",out var pe)&&pe.ValueKind==JsonValueKind.Object)foreach(var x in pe.EnumerateObject())p[x.Name]=x.Value.ToString(); items.Add(new(i.GetProperty("kind").GetString()??"dynamic",i.TryGetProperty("id",out var id)?id.GetString()??"":"",i.TryGetProperty("label",out var l)?l.GetString()??"":"",i.TryGetProperty("thaiLabel",out var t)?t.GetString()??"":"",p,!i.TryGetProperty("resolved",out var r)||r.GetBoolean()));} all.Add(new(m.GetProperty("id").GetString()??"",m.TryGetProperty("name",out var n)?n.GetString()??"":"",m.TryGetProperty("thaiName",out var tn)?tn.GetString()??"":"",m.TryGetProperty("kind",out var k)?k.GetString()??"menu":"menu",items));} Menus=all;}
 public static string BuildCode(BlenderMenu m,BlenderMenuAction a,string ed="มุมมอง3มิติ",string mode="อัตโนมัติ",string sel="อัตโนมัติ"){if(a.Kind=="operator"&&a.Resolved){var c="คำสั่ง(\""+a.Id+"\"";foreach(var p in a.Properties)c+=", "+p.Key+"="+Lit(p.Value);return $"# เมนู: {m.ThaiName} / {a.ThaiLabel}\nwith บริบท(\"{ed}\", mode=\"{mode}\", selection=\"{sel}\"):\n    {c})\n";}return $"# เมนู: {m.ThaiName}\n# รายการนี้ต้องใช้บริบท UI หรือเป็นคำสั่งแบบไดนามิก: {a.ThaiLabel}\n";}
 static string Lit(string v)=>v switch{"True"or"False"or"None"=>v,_ when double.TryParse(v,out _)=>v,_=>"\""+v.Replace("\\","\\\\").Replace("\"","\\\"")+"\""};
}
